          lv_obj_set_style_bg_opa(t, LV_OPA_100 - j * 15, 0);
          lv_obj_set_pos(t, (int)g_anim.balls[i].x,
                         (int)g_anim.balls[i].y);
          g_anim.balls[i].trail[j] = t;
          g_anim.balls[i].trail_x[j] = g_anim.balls[i].x;
          g_anim.balls[i].trail_y[j] = g_anim.balls[i].y;
        }

      /* Create main ball */

      g_anim.balls[i].ball = lv_obj_create(parent);
      lv_obj_remove_style_all(g_anim.balls[i].ball);
      lv_obj_set_size(g_anim.balls[i].ball,
                      (int)(g_anim.balls[i].radius * 2),
                      (int)(g_anim.balls[i].radius * 2));
      lv_obj_set_style_radius(g_anim.balls[i].ball, LV_RADIUS_CIRCLE, 0);
      lv_obj_set_style_bg_color(g_anim.balls[i].ball,
                                g_anim.balls[i].color, 0);
      lv_obj_set_style_bg_opa(g_anim.balls[i].ball, LV_OPA_100, 0);
      lv_obj_set_pos(g_anim.balls[i].ball,
                     (int)g_anim.balls[i].x,
                     (int)g_anim.balls[i].y);
    }
}

static void update_balls(void)
{
  int i, j;
  int sw = lv_display_get_horizontal_resolution(NULL);
  int sh = lv_display_get_vertical_resolution(NULL);

  for (i = 0; i < NUM_BALLS; i++)
    {
      /* Shift trail positions */

      for (j = TRAIL_LENGTH - 1; j > 0; j--)
        {
          g_anim.balls[i].trail_x[j] = g_anim.balls[i].trail_x[j - 1];
          g_anim.balls[i].trail_y[j] = g_anim.balls[i].trail_y[j - 1];
        }

      g_anim.balls[i].trail_x[0] = g_anim.balls[i].x;
      g_anim.balls[i].trail_y[0] = g_anim.balls[i].y;

      /* Update position */

      g_anim.balls[i].x += g_anim.balls[i].vx;
      g_anim.balls[i].y += g_anim.balls[i].vy;

      /* Bounce off walls */

      if (g_anim.balls[i].x < g_anim.balls[i].radius)
        {
          g_anim.balls[i].x = g_anim.balls[i].radius;
          g_anim.balls[i].vx = -g_anim.balls[i].vx * 0.95f;
        }

      if (g_anim.balls[i].x > sw - g_anim.balls[i].radius)
        {
          g_anim.balls[i].x = sw - g_anim.balls[i].radius;
          g_anim.balls[i].vx = -g_anim.balls[i].vx * 0.95f;
        }

      if (g_anim.balls[i].y < g_anim.balls[i].radius)
        {
          g_anim.balls[i].y = g_anim.balls[i].radius;
          g_anim.balls[i].vy = -g_anim.balls[i].vy * 0.95f;
        }

      if (g_anim.balls[i].y > sh - g_anim.balls[i].radius)
        {
          g_anim.balls[i].y = sh - g_anim.balls[i].radius;
          g_anim.balls[i].vy = -g_anim.balls[i].vy * 0.95f;
        }

      /* Add slight gravity and random perturbation */

      g_anim.balls[i].vy += 0.02f;
      g_anim.balls[i].vx += randf(-0.05f, 0.05f);
      g_anim.balls[i].vy += randf(-0.05f, 0.05f);

      /* Speed limit */

      float speed = sqrtf(g_anim.balls[i].vx * g_anim.balls[i].vx +
                          g_anim.balls[i].vy * g_anim.balls[i].vy);
      if (speed > 6.0f)
        {
          g_anim.balls[i].vx *= 6.0f / speed;
          g_anim.balls[i].vy *= 6.0f / speed;
        }

      /* Update trail objects */

      for (j = 0; j < TRAIL_LENGTH; j++)
        {
          float r = g_anim.balls[i].radius * (1.0f - j * 0.12f);
          lv_obj_set_pos(g_anim.balls[i].trail[j],
                         (int)(g_anim.balls[i].trail_x[j] - r),
                         (int)(g_anim.balls[i].trail_y[j] - r));
        }

      /* Update main ball */

      lv_obj_set_pos(g_anim.balls[i].ball,
                     (int)(g_anim.balls[i].x - g_anim.balls[i].radius),
                     (int)(g_anim.balls[i].y - g_anim.balls[i].radius));
    }
}

static void create_title(void)
{
  g_anim.title_label = lv_label_create(lv_screen_active());
  lv_label_set_text(g_anim.title_label, "openvela LVGL Animation");
  lv_obj_set_style_text_color(g_anim.title_label,
                               lv_color_hex(0xFFFFFF), 0);
  lv_obj_set_style_text_font(g_anim.title_label,
                              &lv_font_montserrat_28, 0);
  lv_obj_set_style_text_opa(g_anim.title_label, LV_OPA_80, 0);
  lv_obj_align(g_anim.title_label, LV_ALIGN_TOP_MID, 0, 20);
}

static void create_fps_label(void)
{
  g_anim.fps_label = lv_label_create(lv_screen_active());
  lv_label_set_text(g_anim.fps_label, "FPS: --");
  lv_obj_set_style_text_color(g_anim.fps_label,
                               lv_color_hex(0x00FF88), 0);
  lv_obj_set_style_text_font(g_anim.fps_label,
                              &lv_font_montserrat_16, 0);
  lv_obj_align(g_anim.fps_label, LV_ALIGN_BOTTOM_RIGHT, -20, -20);
}

static void create_wave_canvas(void)
{
  int sw = lv_display_get_horizontal_resolution(NULL);
  int w = sw - 40;
  int h = 120;

  g_anim.wave_canvas = lv_canvas_create(lv_screen_active());
  uint32_t buf_size = LV_CANVAS_BUF_SIZE(w, h, 32, LV_DRAW_BUF_STRIDE_ALIGN);
  void *buf = malloc(buf_size);
  if (!buf)
    {
      return;
    }

  lv_canvas_set_buffer(g_anim.wave_canvas, w, h, LV_COLOR_FORMAT_ARGB8888);
  lv_canvas_set_buffer(g_anim.wave_canvas, w, h, LV_COLOR_FORMAT_ARGB8888);
  lv_obj_align(g_anim.wave_canvas, LV_ALIGN_BOTTOM_MID, 0, -50);
}

static void update_wave(void)
{
  if (!g_anim.wave_canvas)
    {
      return;
    }

  int sw = lv_display_get_horizontal_resolution(NULL);
  int w = sw - 40;
  int h = 120;
  int cx = w / 2;
  int cy = h / 2;

  /* Clear canvas with transparent background */

  lv_canvas_fill_bg(g_anim.wave_canvas, lv_color_hex(0x000000),
                    LV_OPA_TRANSP);

  g_anim.wave_phase += 0.08f;

  /* Draw multiple sine waves with different colors and phases */

  int wave;
  for (wave = 0; wave < 3; wave++)
    {
      uint32_t colors[] = {0x4ECDC4, 0xFF6B6B, 0xFFEAA7};
      float phase_offset = wave * 2.094f; /* 2*PI/3 */
      float amplitude = 30.0f - wave * 5.0f;

      for (int px = 0; px < w - 1; px++)
        {
          float x1 = (float)px / w * 4.0f * PI;
          float x2 = (float)(px + 1) / w * 4.0f * PI;

          int y1 = cy + (int)(sinf(x1 + g_anim.wave_phase + phase_offset) *
                              amplitude);
          int y2 = cy + (int)(sinf(x2 + g_anim.wave_phase + phase_offset) *
                              amplitude);

          /* Draw line between points using Bresenham's algorithm */

          int dx = abs(px + 1 - px);
          int dy = abs(y2 - y1);
          int sx = px < (px + 1) ? 1 : -1;
          int sy = y1 < y2 ? 1 : -1;
          int err = dx - dy;
          int ex = px;
          int ey = y1;

          while (1)
            {
              if (ex >= 0 && ex < w && ey >= 0 && ey < h)
                {
                  lv_canvas_set_px(g_anim.wave_canvas, ex, ey,
                                   lv_color_hex(colors[wave]),
                                   LV_OPA_80);
                }

              if (ex == px + 1 && ey == y2)
                {
                  break;
                }

              int e2 = 2 * err;
              if (e2 > -dy)
                {
                  err -= dy;
                  ex += sx;
                }

              if (e2 < dx)
                {
                  err += dx;
                  ey += sy;
                }
            }
        }
    }
}

static void update_fps(void)
{
  g_anim.frame_count++;
  uint32_t now = lv_tick_get();
  uint32_t elapsed = now - g_anim.last_tick;

  if (elapsed >= 1000)
    {
      uint32_t fps = g_anim.frame_count * 1000 / elapsed;
      char buf[32];
      snprintf(buf, sizeof(buf), "FPS: %lu  Frames: %lu",
               (unsigned long)fps, (unsigned long)g_anim.frame_count);
      lv_label_set_text(g_anim.fps_label, buf);
      g_anim.frame_count = 0;
      g_anim.last_tick = now;
    }
}

static void anim_timer_cb(lv_timer_t *timer)
{
  update_balls();
  update_wave();
  update_fps();
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;

  if (lv_is_initialized())
    {
      LV_LOG_ERROR("LVGL already initialized! aborting.");
      return -1;
    }

#ifdef CONFIG_BOARDCTL
#  ifndef CONFIG_NSH_ARCHINIT
  boardctl(BOARDIOC_INIT, 0);
#  endif
#endif

  lv_init();
  lv_nuttx_dsc_init(&info);

#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif

#ifdef CONFIG_INPUT_TOUCHSCREEN
  info.input_path = "/dev/input0";
#endif

  lv_nuttx_init(&info, &result);

  if (result.disp == NULL)
    {
      LV_LOG_ERROR("Display initialization failure!");
      return 1;
    }

  /* Set dark background */

  lv_obj_set_style_bg_color(lv_screen_active(),
                             lv_color_hex(0x1A1A2E), 0);
  lv_obj_set_style_bg_opa(lv_screen_active(), LV_OPA_100, 0);

  /* Seed random number generator */

  srand(lv_tick_get());

  /* Initialize animation elements */

  memset(&g_anim, 0, sizeof(g_anim));
  g_anim.last_tick = lv_tick_get();

  create_title();
  create_fps_label();
  init_balls();
  create_wave_canvas();

  /* Create animation timer - 16ms interval (~60 FPS target) */

  lv_timer_create(anim_timer_cb, 16, NULL);

  /* Main loop */

  while (1)
    {
      uint32_t idle = lv_timer_handler();
      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }

  return 0;
}
"}

